def equilibrium_index(stock):
    total = sum(stock)   # compute total sum once
    left_sum = 0
    for i in range(len(stock)):
        # right_sum = total - left_sum - stock[i]
        if left_sum == total - left_sum - stock[i]:
            return i
        left_sum += stock[i]  # accumulate left sum
    return -1

