def longest_balanced_route(distances):
    n = len(distances)
    max_len = 0
    for i in range(n):
        pos = neg = 0
        for j in range(i, n):
            if distances[j] > 0: pos += 1
            elif distances[j] < 0: neg += 1
            if pos == neg:
                max_len = max(max_len, j - i + 1)
    return max_len

