def longest_balanced_route(distances):
    # Transform: +1 for positive, -1 for negative, 0 for zero
    transformed = []
    for d in distances:
        if d > 0: transformed.append(1)
        elif d < 0: transformed.append(-1)
        else: transformed.append(0)

    first_seen = {0: -1}  # prefix_sum -> earliest index it occurred
    prefix = 0
    max_len = 0

    for i, val in enumerate(transformed):
        prefix += val
        if prefix in first_seen:
            # subarray from first_seen[prefix]+1 to i has sum 0
            max_len = max(max_len, i - first_seen[prefix])
        else:
            first_seen[prefix] = i  # record first occurrence only

    return max_len

