def longest_k_distinct(menu, k):
    if k == 0 or not menu:
        return 0
    n = len(menu)
    max_len = 0
    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(menu[j])
            if len(seen) <= k:
                max_len = max(max_len, j - i + 1)
            else:
                break  # adding more chars only increases distinct count
    return max_len
